/// <summary>
/// Added logic to enable tax integration adjustment for vendor invoices.
/// </summary>
/// <param name = "_tableId">Source table number</param>
/// <param name = "_recId">Source record id</param>
/// <returns>true, if the tax integration is enabled for the transaction otherwise false</returns>
public static boolean isEnabledForTransaction(RefTableId _tableId, RefRecId _recId)
{
    boolean isEnabled = next isEnabledForTransaction(_tableId, _recId);
    switch (_tableId)
    {
        case tableNum(VendInvoiceInfoTable):
        case tableNum(VendInvoiceInfoLine):
        case tableNum(VendInvoiceTrans):
        case tableNum(PurchTable):
        case tableNum(PurchLine):
        case tableNum(MarkupTrans):
            isEnabled = true;
            break;
    }

    return isEnabled;
}
